const articles = [];

for (const item of $input.all()) {
  const results = item.json.results || [];

  for (const article of results) {
    articles.push({
      title: article.title,
      url: article.url,
      summary: (article.content || "").substring(0, 300),
    });
  }
}

return [
  {
    json: {
      articles,
    },
  },
];

// Day-lock: stamp each post with next week's matching weekday date at 06:00 EAT.
// From a Friday run, Monday = Fri+3 ... Friday = Fri+7. The date rides in a
// [[go:YYYY-MM-DD]] marker prepended to the post (listener strips it -> byte-clean LinkedIn text).
const order = { monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5 };
const posts = ($input.first().json.output && $input.first().json.output.posts) || [];
const sorted = [...posts].sort((a, b) => {
  const da = order[String(a.day || '').toLowerCase()] || 99;
  const db = order[String(b.day || '').toLowerCase()] || 99;
  return da - db || (Number(a.option) || 0) - (Number(b.option) || 0);
});

const EAT = 3 * 60 * 60 * 1000; // Africa/Nairobi, fixed UTC+3
const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const mons = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

// next week's Monday in EAT (from a Friday run this is +3 days)
const wNow = new Date(Date.now() + EAT);
const dow = wNow.getUTCDay();
let toMon = (1 - dow + 7) % 7; if (toMon === 0) toMon = 7;
const monY = wNow.getUTCFullYear(), monM = wNow.getUTCMonth(), monD = wNow.getUTCDate() + toMon;

return sorted.map((p) => {
  const dayIdx = order[String(p.day || '').toLowerCase()] || 1;
  const wall = new Date(Date.UTC(monY, monM, monD + (dayIdx - 1), 6, 0, 0, 0)); // 06:00 EAT that day
  const y = wall.getUTCFullYear(), m = wall.getUTCMonth() + 1, d = wall.getUTCDate();
  const dateStr = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  const niceDate = `${days[wall.getUTCDay()]} ${String(d).padStart(2, '0')} ${mons[wall.getUTCMonth()]}`;

  const day = String(p.day || '').toUpperCase();
  const opt = p.option != null ? p.option : '?';
  const dev = Array.isArray(p.development) ? p.development : (p.development ? [p.development] : []);
  const devLines = dev.map((l) => {
    const s = String(l).trim();
    return /^(→|•|-|\*)/.test(s) ? s : '→ ' + s;
  }).join('\n');
  const tags = Array.isArray(p.hashtags) ? p.hashtags.join(' ') : (p.hashtags || '');
  const post = [p.hook, '', devLines, '', p.insight, '', p.question, '', tags]
    .join('\n').replace(/\n{3,}/g, '\n\n').trim();

  const markedPost = `[[go:${dateStr}]]\n${post}`;                    // what Send Post sends
  const context = `📅 ${day} — Option ${opt} of 3 · goes live ${niceDate} 6:00 AM EAT\nSource: ${p.source_title || ''} — ${p.source_url || ''}`;
  return { json: { day, option: p.option, context, post, markedPost, targetDate: dateStr } };
});

// Normalize the Data Table 'get' result to a single { topics } item (empty string if unset).
const j = $input.first() ? $input.first().json : {};
const topics = j && (j.value || j.next_topics) ? String(j.value || j.next_topics) : '';
return [{ json: { topics } }];
